sqls.sql:

SELECT
    a.project_id, a.site_id, a.district_code,
    a.project_name, a.apply_direction, a.apply_direction_project_name,
    a.project_location, a.implement_unit, a.project_intro, a.project_status,
    a.approval_time, a.approval_amount, a.approval_grant_time, a.approval_grant_amount,
    a.acceptance_time, a.acceptance_grant_time, a.acceptance_grant_amount,
    a.performance_grant_time_1, a.performance_grant_amount_1,
    a.performance_grant_time_2, a.performance_grant_amount_2,
    a.performance_grant_time_3, a.performance_grant_amount_3,
    a.total_grant_amount, a.status, a.reviewer, a.review_time, a.review_opinion,
    a.created_by, a.created_at, a.updated_by, a.updated_at,
    s.site_name, s.company_name, s.tyshxym
FROM wsbs.RECRUIT_SITE_PROJECT a
INNER JOIN wsbs.RECRUIT_SITE_INFO s ON s.site_id = a.site_id
WHERE 1=1
@siteId{and a.site_id = :siteId}
@tyshxym{and s.tyshxym = :tyshxym}
@districtCode{and a.district_code = :districtCode}
@projectName{and a.project_name like '%' || :projectName || '%'}
@applyDirection{and a.apply_direction = :applyDirection}
@projectStatus{and a.project_status = :projectStatus}
@status{and a.status = :status}
@keyword{and (a.project_name like '%' || :keyword || '%'
    or a.apply_direction_project_name like '%' || :keyword || '%'
    or a.project_location like '%' || :keyword || '%'
    or a.implement_unit like '%' || :keyword || '%'
    or a.project_intro like '%' || :keyword || '%')}
ORDER BY a.updated_at DESC, a.project_id DESC


SELECT
    a.warning_id, a.rule_id, a.rule_code, a.rule_name, a.target_type, a.target_id,
    a.site_id, a.project_id, a.asset_id, a.tyshxym, a.district_code,
    a.warning_level, a.warning_status, a.warning_content, a.metric_value, a.threshold_value,
    a.first_trigger_time, a.last_trigger_time, a.trigger_count,
    a.handle_by, a.handle_time, a.handle_remark, a.created_at, a.updated_at,
    s.site_name, p.project_name, ast.asset_name
FROM wsbs.RECRUIT_SITE_WARNING a
LEFT JOIN wsbs.RECRUIT_SITE_INFO s ON s.site_id = a.site_id
LEFT JOIN wsbs.RECRUIT_SITE_PROJECT p ON p.project_id = a.project_id
LEFT JOIN wsbs.RECRUIT_SITE_ASSET ast ON ast.asset_id = a.asset_id
WHERE 1=1
@warningId{and a.warning_id = :warningId}
@siteId{and a.site_id = :siteId}
@projectId{and a.project_id = :projectId}
@assetId{and a.asset_id = :assetId}
@targetType{and a.target_type = :targetType}
@warningLevel{and a.warning_level = :warningLevel}
@warningStatus{and a.warning_status = :warningStatus}
@districtCode{and a.district_code = :districtCode}
@keyword{and (a.rule_name like '%' || :keyword || '%'
    or a.warning_content like '%' || :keyword || '%'
    or s.site_name like '%' || :keyword || '%'
    or p.project_name like '%' || :keyword || '%'
    or ast.asset_name like '%' || :keyword || '%')}
ORDER BY a.last_trigger_time DESC, a.warning_id DESC


SELECT
    a.rule_id, a.rule_code, a.rule_name, a.target_type, a.warning_level,
    a.condition_config, a.content_template, a.description, a.enabled, a.sort_no,
    a.created_by, a.created_at, a.updated_by, a.updated_at
FROM wsbs.RECRUIT_SITE_WARNING_RULE a
WHERE 1=1
@targetType{and a.target_type = :targetType}
@warningLevel{and a.warning_level = :warningLevel}
@enabled{and a.enabled = :enabled}
@keyword{and (a.rule_code like '%' || :keyword || '%'
    or a.rule_name like '%' || :keyword || '%'
    or a.description like '%' || :keyword || '%')}
ORDER BY a.target_type, a.sort_no, a.rule_id


SELECT
    a.rectification_id, a.warning_id, a.rule_id, a.rule_code, a.rule_name,
    a.target_type, a.target_id, a.site_id, a.project_id, a.asset_id,
    a.tyshxym, a.district_code, a.rectification_status,
    a.report_file_key, a.report_file_name, a.uploader_name, a.uploader_id, a.upload_time,
    a.created_by, a.created_at, a.updated_by, a.updated_at,
    s.site_name, p.project_name, ast.asset_name
FROM wsbs.RECRUIT_SITE_RECTIFICATION a
LEFT JOIN wsbs.RECRUIT_SITE_INFO s ON s.site_id = a.site_id
LEFT JOIN wsbs.RECRUIT_SITE_PROJECT p ON p.project_id = a.project_id
LEFT JOIN wsbs.RECRUIT_SITE_ASSET ast ON ast.asset_id = a.asset_id
WHERE 1=1
@rectificationId{and a.rectification_id = :rectificationId}
@warningId{and a.warning_id = :warningId}
@siteId{and a.site_id = :siteId}
@projectId{and a.project_id = :projectId}
@assetId{and a.asset_id = :assetId}
@rectificationStatus{and a.rectification_status = :rectificationStatus}
@districtCode{and a.district_code = :districtCode}
@keyword{and (a.rule_name like '%' || :keyword || '%'
    or s.site_name like '%' || :keyword || '%'
    or p.project_name like '%' || :keyword || '%'
    or ast.asset_name like '%' || :keyword || '%')}
ORDER BY a.created_at DESC, a.rectification_id DESC
